package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ErrorSampleRateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property error sample rate of observed source ")
  void test_error_sample_rate_v_o_builder() {
    Assertions.assertFalse(ErrorSampleRateVO.nullValue().getErrorSampleRate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ErrorSampleRateVO.tryFrom(null).getErrorSampleRate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, ErrorSampleRateVO.from(1).getErrorSampleRate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ErrorSampleRateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ErrorSampleRateVO.from(1).toString());
  }
}
